/**
 * Card images: the League wiki's copy of each card (744×1039, the print
 * resolution Riot publishes), mirrored onto this server on first use.
 *
 * `card-images.json` maps a wiki page title to the card's code, e.g.
 * "Defy" → "OGN-045"; battlefields, printed sideways, carry a ":l". It is
 * generated by `npm run sync:cards` and checked in, so nothing is looked up
 * at request time. A card missing from it simply has no picture.
 *
 * The URL is our own `/card-art/<file>`, which serves the stored copy
 * (lib/card-art-store.ts). next/image resizes it (see next.config.ts), so
 * every spot gets a small WebP rather than the ~600 KB PNG.
 */
import images from "./card-images.json";
import { cardWikiTitle } from "./deck";

const MAP = images as Record<string, string>;
/** Served by app/card-art/[file]/route.ts from the server's own copy. */
const BASE = "/card-art";

function fileOf(value: string): string {
  return `RB_card_${value.endsWith(":l") ? value.slice(0, -2) : value}.png`;
}

/** Every card file the map knows, e.g. "RB_card_OGN-045.png". */
export const CARD_FILES: ReadonlySet<string> = new Set(Object.values(MAP).map(fileOf));

export interface CardImage {
  /** The print-size image (744×1039, or 1039×744 when landscape). */
  src: string;
  landscape: boolean;
}

function fromCode(value: string): CardImage {
  return { src: `${BASE}/${fileOf(value)}`, landscape: value.endsWith(":l") };
}

/**
 * The image for a card as a decklist names it. Legends live on the wiki under
 * their title alone, the same rule as `cardWikiUrl`, with the full name as a
 * fallback in case a page is filed the other way.
 */
export function cardImage(name: string, { legend = false }: { legend?: boolean } = {}): CardImage | null {
  const value = MAP[cardWikiTitle(name, { legend })] ?? MAP[name.trim()];
  return value ? fromCode(value) : null;
}
